package android.ext.ai;

/* OpenAI function-calling tool definitions exposed to the model. Names must match the Lua dispatcher in AiScriptSource. */
public final class AiTools {

    private AiTools() {
    }

    public static final java.lang.String TOOLS_JSON = "["
            + "{\"type\":\"function\",\"function\":{\"name\":\"search_number\",\"description\":\"Search the attached game process memory for a known value (for example the currently displayed amount of coins or HP). Returns the number of matches. Ask the user for the current visible value first.\",\"parameters\":{\"type\":\"object\",\"properties\":{\"value\":{\"type\":\"string\",\"description\":\"The value to search for, as a string (group search syntax like '90;120' is allowed)\"},\"data_type\":{\"type\":\"string\",\"enum\":[\"byte\",\"word\",\"dword\",\"qword\",\"float\",\"double\"],\"description\":\"Memory value type. dword fits most game resources; float fits HP bars and decimals\"}},\"required\":[\"value\"]}}},"
            + "{\"type\":\"function\",\"function\":{\"name\":\"refine_number\",\"description\":\"Filter the current search results down to entries that now equal the given value. Use after the value changed in the game: ask the user to change it (spend coins, take damage), then refine with the new value. Returns the remaining count.\",\"parameters\":{\"type\":\"object\",\"properties\":{\"value\":{\"type\":\"string\",\"description\":\"The new value to filter by\"},\"data_type\":{\"type\":\"string\",\"enum\":[\"byte\",\"word\",\"dword\",\"qword\",\"float\",\"double\"]}},\"required\":[\"value\"]}}},"
            + "{\"type\":\"function\",\"function\":{\"name\":\"get_results\",\"description\":\"Fetch rows from the current search results (address, value, flags). Addresses are hexadecimal strings like 0x77481C8670.\",\"parameters\":{\"type\":\"object\",\"properties\":{\"count\":{\"type\":\"integer\",\"description\":\"How many rows to fetch, default 20\"}},\"required\":[]}}},"
            + "{\"type\":\"function\",\"function\":{\"name\":\"read_values\",\"description\":\"Read current values at specific addresses. Pass the exact addresses from previous results.\",\"parameters\":{\"type\":\"object\",\"properties\":{\"addresses\":{\"type\":\"array\",\"items\":{\"type\":\"object\",\"properties\":{\"address\":{\"type\":\"string\",\"description\":\"Address, hex like 0x77481C8670\"},\"data_type\":{\"type\":\"string\",\"enum\":[\"byte\",\"word\",\"dword\",\"qword\",\"float\",\"double\"]}},\"required\":[\"address\"]}}},\"required\":[\"addresses\"]}}},"
            + "{\"type\":\"function\",\"function\":{\"name\":\"write_values\",\"description\":\"Write a new value into the game memory at the given address.\",\"parameters\":{\"type\":\"object\",\"properties\":{\"address\":{\"type\":\"string\",\"description\":\"Address, hex like 0x77481C8670\"},\"value\":{\"type\":\"string\",\"description\":\"New value to write\"},\"data_type\":{\"type\":\"string\",\"enum\":[\"byte\",\"word\",\"dword\",\"qword\",\"float\",\"double\"]}},\"required\":[\"address\",\"value\"]}}},"
            + "{\"type\":\"function\",\"function\":{\"name\":\"freeze_values\",\"description\":\"Freeze a value at the given address so the game cannot change it (unlimited money / immortal HP). The value is kept constant until unfrozen in the saved list.\",\"parameters\":{\"type\":\"object\",\"properties\":{\"address\":{\"type\":\"string\",\"description\":\"Address, hex like 0x77481C8670\"},\"value\":{\"type\":\"string\",\"description\":\"Value to keep frozen\"},\"data_type\":{\"type\":\"string\",\"enum\":[\"byte\",\"word\",\"dword\",\"qword\",\"float\",\"double\"]}},\"required\":[\"address\",\"value\"]}}},"
            + "{\"type\":\"function\",\"function\":{\"name\":\"clear_results\",\"description\":\"Discard the current search results to start a fresh search.\",\"parameters\":{\"type\":\"object\",\"properties\":{},\"required\":[]}}},"
            + "{\"type\":\"function\",\"function\":{\"name\":\"get_target_info\",\"description\":\"Get information about the currently attached game process (name, pid, etc.). Returns no target when nothing is attached.\",\"parameters\":{\"type\":\"object\",\"properties\":{},\"required\":[]}}}"
            + "]";
}
